  (* [comment removed for export] *)
  Lemma bundle_stack : forall LF m m1 lo shi l h,
    as_RFS H LF m -> ACONST m -> stack0 m lo shi -> munch [(l, h)]%Z m m1 -> wmono bsegs m m1 -> aceil <= l ->
    as_RFS H LF m1 /\ ACONST m1 /\ stack0 m1 lo shi.
  Proof.
    intros LF m m1 lo shi l h RF AC SK MU WM CE. pose proof aceil_facts as (AF & _).
    pose proof (RFS_fsb _ HH _ _ RF) as (B1 & B2 & B3 & B4).
    split; [| split].
    - eapply (ah_RFS_frame _ HH); [exact RF| exact MU| exact WM|]. apply Forall_cons; [| apply Forall_nil].
      left. cbn [fst snd]. unfold ATLS_PRIV_LO, ATLS_PRIV_HI, ATP, AFS_SIZE in *. lia.
    - eapply ACONST_frame; [exact AC| exact MU| exact WM|]. apply Forall_cons; [| apply Forall_nil]. apply aconst_ok_hi. cbn [fst snd]. unfold AHI_LO. lia.
    - eapply stack0_transport; [exact SK| exact MU| exact WM|]. apply Forall_cons; [| apply Forall_nil]. apply stack0_ok_app. cbn [fst snd]. unfold AHI_LO. lia.
  Qed.

