Definition mi_segA_post (sp gp tp s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (LB : list block) (LF : list fframe) (L : list svce) (R EX ioc regb first allocb schedb lo shi : Z) (j16 : list byte) (ra s0 s1 s2 s3 : word) (m : mem)
    : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a4 a5 a6 a7 t3 t4 t5 t6 m' (XS : list (Z * Z)) (j0 j1 : list byte),
    ms' = MS (mkR (Z_to_bv 64 AMI_RET0) (Z_to_bv 64 (bv_unsigned sp + -96)) gp tp t0 t1 t2
                  (Z_to_bv 64 R) (Z_to_bv 64 EX) (Z_to_bv 64 regb) (Z_to_bv 64 (bv_unsigned sp + -88)) (Z_to_bv 64 P_A_CREATE_SSVC) (Z_to_bv 64 ioc) a4 a5 a6 a7
                  s2 (Z_to_bv 64 2147450880) s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_A_DO_USE_SERVICE) fc None m' (seg_rom bsegs)
    /\ Forall (fs_scratch H LF) XS
    /\ munch ([(lo, bv_unsigned sp)]%Z ++ XS) m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp + -96)
    (* [comment removed for export] *)
    /\ rw_cells bsegs m' (bv_unsigned sp + -96) [CB 8 j0]
    /\ rw_cells bsegs m' (bv_unsigned sp + -88) [C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 AG_ID_SSVC)]
    /\ rw_cells bsegs m' (bv_unsigned sp + -72) [C8 (Z_to_bv 64 AMI_RET1)]
    (* [comment removed for export] *)
    /\ rw_cells bsegs m' (bv_unsigned sp + -64) [CB 16 j1]
    /\ rw_cells bsegs m' (bv_unsigned sp + -48) [C8 (Z_to_bv 64 0)]
    /\ rw_cells bsegs m' (bv_unsigned sp + -40) [C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]
    /\ rw_cells bsegs m' EX (AnyExecCells EX ioc j16)
    /\ ro_cells bsegs m' ioc (IoCtxCells allocb regb schedb)
    /\ ARegistry LB m' regb ioc first 0
    /\ ASvcChain m' first L
    /\ AAllocImpl LB m' allocb /\ AXStatics2 m'
    /\ as_RFS H LF m' /\ ACONST m' /\ stack0 m' lo shi.
