Definition mi_segC_post (sp gp tp t0 t1 t2 a6 a7 s0 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (q x lo : Z) (jt : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a2 a3 a4 a5 m',
    ms' = MS (mkR (Z_to_bv 64 AMI_RET3) (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2 s0 (Z_to_bv 64 (q + 32))
                  (Z_to_bv 64 (q + 72)) (Z_to_bv 64 (bv_unsigned sp + -56)) a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_A_VEC_STATEP_EMPLACE_BACK) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp + -64); (bv_unsigned sp + -56, bv_unsigned sp + -48); (q + 32, q + 72)]%Z m m'
    /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp + -64)
    /\ APMutex m' (q + 32) EBUSY
    /\ rw_cells bsegs m' (bv_unsigned sp + -64) [CB 8 (firstn 8 jt)]      (* [comment removed for export] *)
    /\ rw_cells bsegs m' (bv_unsigned sp + -56) [C8 (Z_to_bv 64 x)]
    /\ ACONST m'.

Lemma mi_segC : forall (pcv sp gp tp t0 t1 t2 rax s1 a0 a1 a2 a3 a4 a5 a6 a7 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) fc (m : mem) (R v q x lo : Z) (jt : list byte),
  (pcv = Z_to_bv 64 AMI_RET2 \/ pcv = ret_pc (Z_to_bv 64 AMI_RET2)) ->
  ro_cells bsegs m (v + 48) [C8 (wz (q + 32))] -> aapp v NEWSZ_SSVC -> v mod 8 = 0 -> accessible m (v + 48) 8 ->
  APMutex m (q + 32) 0 -> aapp q SZ_SPCI_IMPL -> q mod 16 = 0 -> (v + NEWSZ_SSVC <= q \/ q + SZ_SPCI_IMPL <= v) ->
  ro_cells bsegs m R [C8 (wz x)] -> aplace R 16 -> (R + 16 <= lo \/ bv_unsigned sp <= R) -> R mod 8 = 0 -> accessible m R 16 -> 0 <= x < 2^64 -> (R + 16 <= q \/ q + SZ_SPCI_IMPL <= R) ->
  rw_cells bsegs m (bv_unsigned sp + -64) [CB 16 jt] ->      (* [comment removed for export] *)
  stk bsegs m lo (bv_unsigned sp + -64) -> lo + 64 + MTX_LOCK_STACK <= bv_unsigned sp -> aceil <= lo ->
  mem_inv bsegs m -> ACONST m ->
  evt bsegs (mi_segC_post sp gp tp t0 t1 t2 a6 a7 (Z_to_bv 64 R) (Z_to_bv 64 (v + 48)) (Z_to_bv 64 ASHADOW_BASE) s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc q x lo jt m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2 (Z_to_bv 64 R) s1
             a0 a1 a2 a3 a4 a5 a6 a7 (Z_to_bv 64 (v + 48)) (Z_to_bv 64 ASHADOW_BASE) s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F pcv fc None m (seg_rom bsegs)).
