(* [comment removed for export] *)
(* [comment removed for export] *)
Definition mi_segD_post (sp gp tp s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 a4 a5 a6 a7 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (q lo : Z) (rav s0v s1v s2v s3v : word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a0 a1 a2 a3 m',
    ms' = MS (mkR rav sp gp tp t0 t1 t2 s0v s1v a0 a1 a2 a3 a4 a5 a6 a7 s2v s3v s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc rav) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp); (q + 32, q + 72)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ APMutex m' (q + 32) 0
    /\ ACONST m'.

Lemma mi_segD : forall (pcv sp gp tp t0 t1 t2 rax s0x s2x s3x a0 a1 a2 a3 a4 a5 a6 a7 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) fc (m : mem) (q lo : Z) (rav s0v s1v s2v s3v w8 w16 : word) (j8 : list byte),
  (pcv = Z_to_bv 64 AMI_RET3 \/ pcv = ret_pc (Z_to_bv 64 AMI_RET3)) ->
  APMutex m (q + 32) EBUSY -> aapp q SZ_SPCI_IMPL ->
  rw_cells bsegs m (bv_unsigned sp + -64) [CB 8 j8] ->     (* [comment removed for export] *)
  rw_cells bsegs m (bv_unsigned sp + -56) [C8 w8] ->
  rw_cells bsegs m (bv_unsigned sp + -48) [C8 w16] ->
  rw_cells bsegs m (bv_unsigned sp + -40) [C8 s3v; C8 s2v; C8 s1v; C8 s0v; C8 rav] ->
  stk bsegs m lo (bv_unsigned sp + -64) -> lo + 64 + MTX_UNLOCK_STACK <= bv_unsigned sp -> aceil <= lo ->
  bv_unsigned rav mod 2 = 0 ->
  mem_inv bsegs m -> ACONST m ->
  evt bsegs (mi_segD_post sp gp tp s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 a4 a5 a6 a7 t3 t4 t5 t6 F fc q lo rav s0v s1v s2v s3v m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2 s0x (Z_to_bv 64 (q + 32))
             a0 a1 a2 a3 a4 a5 a6 a7 s2x s3x s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
